"""Meridian CRM 4.2 EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def _value(row: dict, key: str) -> str:
    value = row.get(key, "")
    return "" if value is None else str(value)


def _fixed(value: str, width: int) -> str:
    return value[:width].ljust(width)


def _cents(value: object) -> int:
    if value is None or str(value).strip() == "":
        return 0
    try:
        amount = Decimal(str(value))
    except InvalidOperation:
        amount = Decimal(0)
    return int((amount * Decimal(100)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def _zpad(value: int, width: int) -> str:
    return str(value).zfill(width)


def format_account(row: dict) -> str:
    """Return one 77-character EXPORT_ACCT record without a newline."""
    acct_id = _value(row, "ACCT_ID")
    acct_nm = _value(row, "ACCT_NM")
    region_cd = _value(row, "REGION_CD")

    ann_rev = row.get("ANN_REV", "")
    cred_hold = _value(row, "CRED_HOLD") or "N"
    create_dt = _value(row, "CREATE_DT") or "00000000"

    return (
        _fixed(acct_id, 10)
        + _fixed(acct_nm, 40)
        + _fixed(region_cd, 3)
        + _zpad(_cents(ann_rev), 15)
        + cred_hold
        + create_dt
    )
